import numpy as np, json, math, time, sys
from joint import *
ml,data=load()
mu,sig,q=joint_fit(ml,data)
cells=sorted(ml)
def golden(f,lo,hi,it=60):
    for _ in range(it):
        a=lo+(hi-lo)*0.382; b=lo+(hi-lo)*0.618
        if f(a)<f(b): hi=b
        else: lo=a
    return 0.5*(lo+hi)
def trunc_fit(sd):
    ks=[k for k in cells if len(sd[k])>0]
    S={k:sd[k].sum() for k in ks}; SS={k:(sd[k]**2).sum() for k in ks}; n={k:len(sd[k]) for k in ks}
    def nll(k,m,s):
        return n[k]*(math.log(s)+math.log(Phi((C-m)/s)))+(SS[k]-2*m*S[k]+n[k]*m*m)/(2*s*s)
    m={k:sd[k].mean() for k in ks}; s=0.09
    for it in range(25):
        for k in ks: m[k]=golden(lambda x:nll(k,x,s),m[k]-0.3,m[k]+0.3)
        s=golden(lambda x:sum(nll(k,m[k],x) for k in ks),0.05,0.15)
    # q per batch: pooled n / sum(N*Phi)
    qq={}
    for b in (256,512,1024):
        kb=[k for k in ks if k[1]==b]
        qq[b]=sum(n[k] for k in kb)/sum(N*Phi((C-m[k])/s) for k in kb)
    return m,s,qq
rng=np.random.default_rng(int(sys.argv[1])); R=int(sys.argv[2])
Q={'q04':((0.001,512,'wsd',0.5,'bf16'),(0.001,512,'wsd',1.0,'bf16')),
   'q10':((0.001,512,'wsd',1.0,'bf16'),(0.001,1024,'wsd',1.0,'bf16')),
   'q03':((0.0003,512,'cosine',0.5,'bf16'),(0.001,512,'cosine',0.5,'bf16'))}
Rc={'r2':(0.001,512,'cosine',0.5,'bf16'),'r3':(0.001,512,'wsd',1.0,'bf16')}
errs={}
def add(k,v): errs.setdefault(k,[]).append(v)
for r in range(R):
    sd={}; truthG={}; realmean={}
    for k in cells:
        x=rng.normal(mu[k],sig,N); realmean[k]=x.mean()
        pre=rng.random(N)>q[k[1]]; g=x>C
        sd[k]=x[(~pre)&(~g)]
        truthG[k]=((g&~pre).sum()/N, g.sum()/N)
    m2,s2,q2=trunc_fit(sd)
    for qid,(a,b) in Q.items():
        add(qid+'_pop',(m2[b]-m2[a])-(mu[b]-mu[a])); add(qid+'_real',(m2[b]-m2[a])-(realmean[b]-realmean[a]))
    for rid,k in Rc.items():
        Pg=1-Phi((C-m2[k])/s2)
        add(rid+'_F1_vsGF',Pg-truthG[k][1]); add(rid+'_F2_vsPF',q2[k[1]]*Pg-truthG[k][0])
        add(rid+'_F1_vsPopGF',Pg-(1-Phi((C-mu[k])/sig))); add(rid+'_F2_vsPopPF',q2[k[1]]*Pg-q[k[1]]*(1-Phi((C-mu[k])/sig)))
json.dump(errs,open('sim2_%s.json'%sys.argv[1],'w'))
